import { categoryMap } from "../types";
import { CDN_URL } from "../utils/constants";
import { ensureElement } from "../utils/utils";
import { Component } from "./base/Component";
export class ProductCard extends Component {
    constructor(events, elementsBlock, id, title, description, category, image, price) {
        super(events, elementsBlock);
        this.id = id;
        this.title = title;
        this.description = description;
        this.category = category;
        this.image = image;
        this.price = price;
        this.render();
    }
    render() {
        const cardCategory = ensureElement('.card__category', this.element);
        const cardTitle = ensureElement('.card__title', this.element);
        const cardImage = ensureElement('.card__image', this.element);
        const cardPrice = ensureElement('.card__price', this.element);
        cardCategory.textContent = this.category;
        const categoryClass = categoryMap[this.category.toLocaleLowerCase()];
        if (categoryClass) {
            cardCategory.classList.add(`card__category_${categoryClass}`);
        }
        cardTitle.textContent = this.title;
        cardImage.src = CDN_URL + this.image;
        cardPrice.textContent = this.price ? `${this.price} синапсов` : `Бесценно`;
    }
    addEventListeners() {
        this.element.addEventListener('click', () => {
            this.events.emit('card:click', this);
        });
    }
}
