import { categoryMap } from "../types";
import { CDN_URL } from "../utils/constants";
import { ensureElement } from "../utils/utils";
import { Modal } from "./base/Modal";
export class ProductModal extends Modal {
    constructor(elementsBlock, events, name) {
        super(events, elementsBlock);
        this.name = name;
    }
    render(product, isProductInBasket) {
        const productImage = ensureElement('.card__image', this.element);
        const productCategory = ensureElement('.card__category', this.element);
        const productTitle = ensureElement('.card__title', this.element);
        const productText = ensureElement('.card__text', this.element);
        const productPrice = ensureElement('.card__price', this.element);
        const productButton = ensureElement('.button', this.element);
        productImage.src = CDN_URL + product.image;
        productCategory.textContent = product.category;
        const categoryClass = categoryMap[product.category.toLocaleLowerCase()];
        if (categoryClass) {
            productCategory.classList.add(`card__category_${categoryClass}`);
        }
        productTitle.textContent = product.title;
        productText.textContent = product.description;
        if (product.price) {
            productPrice.textContent = `${product.price} синапсов`;
            productButton.disabled = false;
            if (isProductInBasket) {
                productButton.textContent = 'Убрать';
                this.setDeleteHandler(productButton, product);
            }
            else {
                productButton.textContent = 'В корзину';
                this.setAddHandler(productButton, product);
            }
        }
        else {
            productPrice.textContent = `Бесценно`;
            productButton.textContent = 'Не продаётся';
            productButton.disabled = true;
        }
        this.open();
    }
    removeHandler(btn) {
        if (this.productButtonHandler) {
            btn.removeEventListener('click', this.productButtonHandler);
        }
    }
    setAddHandler(btn, product) {
        this.removeHandler(btn);
        this.productButtonHandler = () => {
            this.events.emit('product:put', product);
            this.setDeleteHandler(btn, product);
            btn.textContent = 'Убрать';
            this.close();
        };
        btn.addEventListener('click', this.productButtonHandler);
    }
    setDeleteHandler(btn, product) {
        this.removeHandler(btn);
        this.productButtonHandler = () => {
            this.events.emit('product:delete', product);
            this.setAddHandler(btn, product);
            btn.textContent = 'В корзину';
            this.close();
        };
        btn.addEventListener('click', this.productButtonHandler);
    }
}
