import { ensureElement } from "../../utils/utils";
import { Modal } from "./Modal";
export class Form extends Modal {
    constructor(elementsBlock, events) {
        super(events, elementsBlock);
    }
    eventsEmit() { }
    addEventListeners() {
        super.addEventListeners();
        this.formElement = ensureElement('.form', this.element);
        this.formElement.addEventListener('submit', (event) => {
            event.preventDefault();
            this.eventsEmit();
        });
    }
    render() {
        this.buttonForm = ensureElement('.button_further', this.element);
        this.buttonForm.disabled = true;
        this.errorElement = ensureElement('.form__errors', this.element);
        this.errorElement.style.display = 'none';
        this.open();
    }
}
